import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.ResponseBody;
import org.springframework.web.servlet.mvc.method.annotation.RequestBodyAdvice;

/**
 * Rejects a create-owner request whose normalized telephone (non-digit characters
 * stripped, matching how the create path stores it) is already used by an existing
 * owner, responding 409 Conflict. Applies only to the create endpoint so updates that
 * keep an owner's own telephone are unaffected.
 */
@ControllerAdvice
@Order(Ordered.HIGHEST_PRECEDENCE)
public class OwnerUniqueTelephoneAdvice implements RequestBodyAdvice {

    private final ClinicService clinicService;

    private final OwnerMapper ownerMapper;

    public OwnerUniqueTelephoneAdvice(ClinicService clinicService, OwnerMapper ownerMapper) {
        this.clinicService = clinicService;
        this.ownerMapper = ownerMapper;
    }

    @Override
    public boolean supports(MethodParameter methodParameter, Type targetType,
                            Class<? extends HttpMessageConverter<?>> converterType) {
        Method method = methodParameter.getMethod();
        return OwnerFieldsDto.class.equals(targetType) && method != null
            && "addOwner".equals(method.getName());
    }

    @Override
    public Object afterBodyRead(Object body, HttpInputMessage inputMessage, MethodParameter parameter,
                                Type targetType, Class<? extends HttpMessageConverter<?>> converterType) {
        String telephone = ownerMapper.normalizeTelephone(((OwnerFieldsDto) body).getTelephone());
        if (telephone != null && isTelephoneTaken(telephone)) {
            throw new DuplicateTelephoneException();
        }
        return body;
    }

    private boolean isTelephoneTaken(String telephone) {
        for (Owner existing : clinicService.findAllOwners()) {
            if (telephone.equals(ownerMapper.normalizeTelephone(existing.getTelephone()))) {
                return true;
            }
        }
        return false;
    }

    @Override
    public Object handleEmptyBody(Object body, HttpInputMessage inputMessage, MethodParameter parameter,
                                  Type targetType, Class<? extends HttpMessageConverter<?>> converterType) {
        return body;
    }

    @Override
    public HttpInputMessage beforeBodyRead(HttpInputMessage inputMessage, MethodParameter parameter,
                                           Type targetType, Class<? extends HttpMessageConverter<?>> converterType) {
        return inputMessage;
    }

    @ExceptionHandler(DuplicateTelephoneException.class)
    @ResponseBody
    public ResponseEntity<Void> handleDuplicateTelephone(DuplicateTelephoneException e) {
        return ResponseEntity.status(HttpStatus.CONFLICT).build();
    }

    /** Signals that an owner with the same normalized telephone already exists. */
    static class DuplicateTelephoneException extends RuntimeException {
    }
}

